#include "shaders.h"
#include <stdio.h>
#include <string.h>

#include "shader_sources.inl"   // generated by the build: SHADER_FILES
#include "spirv/table.inl"      // generated when glslc is found, else the committed copy: SPIRV_BLOBS, SPIRV_SOURCE_SHA256

#define SHADER_FILE_COUNT ((uint32_t)(sizeof(SHADER_FILES) / sizeof(SHADER_FILES[0])))
#define SHADER_MAX_INCLUDES 16

const r_shader_file *r_shader_files(uint32_t *count) {
    *count = SHADER_FILE_COUNT;
    return SHADER_FILES;
}

const r_shader_file *r_shader_file_find(const char *name) {
    for (uint32_t i = 0; i < SHADER_FILE_COUNT; ++i)
        if (strcmp(SHADER_FILES[i].name, name) == 0) return &SHADER_FILES[i];
    return NULL;
}

struct assembly {
    char *out;
    size_t capacity, length;
    const char *included[SHADER_MAX_INCLUDES];
    int include_count;
    bool failed;
};

static void emit(assembly *a, const char *text, size_t length) {
    if (a->length + length >= a->capacity) {
        a->failed = true;
        return;
    }
    memcpy(a->out + a->length, text, length);
    a->length += length;
}

static void assemble_file(assembly *a, const char *name) {
    for (int i = 0; i < a->include_count; ++i)
        if (strcmp(a->included[i], name) == 0) return;   // once is enough
    if (a->include_count == SHADER_MAX_INCLUDES) {
        a->failed = true;
        return;
    }
    const r_shader_file *file = r_shader_file_find(name);
    if (!file) {
        fprintf(stderr, "shaders: no file %s\n", name);
        a->failed = true;
        return;
    }
    a->included[a->include_count++] = file->name;
    const char *text = (const char *)file->data, *end = text + file->size;
    while (text < end && !a->failed) {
        const char *line_end = (const char *)memchr(text, '\n', (size_t)(end - text));
        size_t line_length = line_end ? (size_t)(line_end - text + 1) : (size_t)(end - text);
        const char *p = text;
        while (p < text + line_length && (*p == ' ' || *p == '\t')) ++p;
        if (strncmp(p, "#include", 8) == 0) {
            const char *open = (const char *)memchr(p, '"', (size_t)(text + line_length - p));
            const char *close = open ? (const char *)memchr(open + 1, '"', (size_t)(text + line_length - open - 1)) : NULL;
            if (open && close) {
                char included[64];
                size_t n = (size_t)(close - open - 1);
                if (n < sizeof(included)) {
                    memcpy(included, open + 1, n);
                    included[n] = 0;
                    assemble_file(a, included);
                    emit(a, "\n", 1);
                    text += line_length;
                    continue;
                }
            }
        }
        emit(a, text, line_length);
        text += line_length;
    }
}

size_t r_shader_assemble(const char *name, const char *defines, char *out, size_t capacity) {
    assembly a = {out, capacity, 0, {}, 0, false};
    emit(&a, "#version 450 core\n", 18);
    emit(&a, defines, strlen(defines));
    assemble_file(&a, name);
    if (a.failed) return 0;
    out[a.length] = 0;
    return a.length;
}

const r_spirv_blob *r_spirv_find(const char *name) {
    for (size_t i = 0; i < sizeof(SPIRV_BLOBS) / sizeof(SPIRV_BLOBS[0]); ++i)
        if (SPIRV_BLOBS[i].words && strcmp(SPIRV_BLOBS[i].name, name) == 0) return &SPIRV_BLOBS[i];
    return NULL;
}

bool r_spirv_fresh(void) { return strcmp(SPIRV_SOURCE_SHA256, TP_SHADERS_SHA256) == 0; }
